export default function Navbar() {
  return (
    <nav className="flex items-center justify-between px-8 py-4 bg-blue-600 text-white shadow-md">
      <h1 className="text-2xl font-bold">AI Interview Coach</h1>
      <div className="flex space-x-4">
        <a href="/" className="hover:text-blue-200">Home</a>
        <a href="/interview" className="hover:text-blue-200">Interview</a>
        <a href="/feedback" className="hover:text-blue-200">Feedback</a>
      </div>
    </nav>
  );
}
